penpot.ui.open("FEATHER ICONS PLUGIN",`?theme=${penpot.theme}`,{width:292,height:540});penpot.ui.onMessage(e=>{if(e.type==="insert-icon"){let{name:t,svg:o}=e.content;if(!o||!t)return;let n=penpot.createShapeFromSvg(o);n&&(n.name=t,n.x=penpot.viewport.center.x,n.y=penpot.viewport.center.y)}});penpot.on("themechange",e=>{p({type:"theme",content:e})});function p(e){penpot.ui.sendMessage(e)}
